<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Product</title><link rel="stylesheet" href="/assets/css/legacy-style.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="card"><h1>Edit Product</h1><?php foreach (($errors ?? []) as $error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endforeach; ?><p class="hint">Stock quantity is adjusted from <a href="/inventory">Inventory</a> only.</p><form method="post" action="/products/update"><input type="hidden" name="_token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="product_id" value="<?= (int) $row['product_id'] ?>"><label>SKU</label><input name="sku" value="<?= htmlspecialchars((string) ($row['sku'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"><label>Product Name</label><input name="product_name" value="<?= htmlspecialchars($row['product_name'] ?? '', ENT_QUOTES, 'UTF-8') ?>" required><label>Description / Scope</label><textarea name="description" rows="4" placeholder="Example: Web layout, 5 pages, contact form, mobile responsive."><?= htmlspecialchars((string) ($row['description'] ?? ''), ENT_QUOTES, 'UTF-8') ?></textarea><label>Unit Price</label><input name="unit_price" type="number" min="0" step="0.01" value="<?= htmlspecialchars((string) ($row['unit_price'] ?? '0.00'), ENT_QUOTES, 'UTF-8') ?>" required><label>Stock Control</label><select name="stock_control_type"><option value="STOCK_CONTROLLED" <?= (($row['stock_control_type'] ?? 'STOCK_CONTROLLED') === 'STOCK_CONTROLLED') ? 'selected' : '' ?>>Stock Controlled (physical goods)</option><option value="STOCK_NOT_CONTROLLED" <?= (($row['stock_control_type'] ?? 'STOCK_CONTROLLED') === 'STOCK_NOT_CONTROLLED') ? 'selected' : '' ?>>Non Stock Controlled (services)</option></select><label>Current Stock (read-only)</label><input value="<?= (($row['stock_control_type'] ?? 'STOCK_CONTROLLED') === 'STOCK_NOT_CONTROLLED') ? 'N/A' : number_format((float) ($row['stock_qty'] ?? 0), 2) ?>" readonly><label>Status</label><select name="is_active"><option value="1" <?= ((int) ($row['is_active'] ?? 1) === 1) ? 'selected' : '' ?>>Active</option><option value="0" <?= ((int) ($row['is_active'] ?? 1) === 0) ? 'selected' : '' ?>>Inactive</option></select><button type="submit">Update Product</button></form><p><a href="/products">Back to products</a></p></main></body></html>
